scenarios.headers:
Content-Type: text/csv; charset=UTF-8
Content-Disposition: attachment; filename="rebate-{{request.params.rebateId}}-account-upload-errors.csv"
X-Account-Upload-Created-Count: {{result.createdCount}}
X-Account-Upload-Ended-Count: {{result.endedCount}}
X-Account-Upload-Error-Count: {{result.errorCount}}
Access-Control-Expose-Headers: Content-Disposition, X-Account-Upload-Created-Count, X-Account-Upload-Ended-Count, X-Account-Upload-Error-Count
